ed();guide.SelectionChanged+=delegate{overlayAction.IsEnabled=!busy&&libraryPrimaryEnabled();};
 var guideTools=new WrapPanel();guideTools.Children.Add(Button("Guides Tougli",()=>RunDownload(async token=>{var result=TougliReader.Catalogue(await Download("/api/guide/list",token));if(result.Count==0)throw new InvalidDataException("Aucun guide trouvé.");GuideLibrary.Merge(store,result);guides=GuideLibrary.Read(store);filterGuides();await PrepareAllGuides(token);})));guideTools.Children.Add(Button("Guides Ganymède",()=>RunDownload(async token=>{var result=GanymedeReader.Catalogue(await DownloadAddress(GanymedeReader.Site+"/tree?view=list",token));if(result.Count==0)throw new InvalidDataException("Aucun guide français trouvé.");GuideLibrary.Merge(store,result);guides=GuideLibrary.Read(store);filterGuides();})));catalogue.Children.Add(guideTools);var offlineTools=new WrapPanel();offlineTools.Children.Add(Button("Reprendre la préparation complète",()=>PrepareOffline()));offlineTools.Children.Add(Button("Actualiser le guide sélectionné",()=>{var selected=guide.SelectedItem as GuideChoice;if(selected!=null)loadGuide(selected.Slug,true);}));catalogue.Children.Add(offlineTools);body.Children.Add(CompanionTheme.Card(catalogue));
