 void UpdatePreparation(){if(preparationStatus!=null){preparationStatus.Visibility=preparingLibrary?Visibility.Visible:Visibility.Collapsed;preparationStatus.Text="Préparation de la bibliothèque · "+preparedCount+" / "+preparationTotal+" guides prêts";}if(libraryProgress!=null){libraryProgress.Visibility=preparingLibrary?Visibility.Visible:Visibility.Collapsed;libraryProgress.Maximum=Math.Max(1,preparationTotal);libraryProgress.Value=preparedCount;}}
 async Task PrepareAllGuides(CancellationToken token){if(cancel!=null)cancel.CancelAfter(TimeSpan.FromMinutes(30));preparingLibrary=true;UpdatePreparation();try{var result=await GuideDownloads.Prepare(store,GuideLibrary.Read(store),async (guide,ct)=>GanymedeReader.IsGuide(guide.Slug)?GanymedeReader.Normalise(await DownloadAddress(GanymedeReader.Url(guide.Slug),ct)):await Download("/api/guide/details/"+guide.Slug,ct),progress=>{preparedCount=progress.Ready;preparationTotal=progress.Total;message="Préparation complète · "+progress.Ready+" / "+progress.Total+" guides prêts"+(progress.Failed==0?"":" · "+progress.Failed+" indisponibles")+(String.IsNullOrEmpty(progress.Current)?"":"\n"+progress.Current);if(libraryNotice!=null)libraryNotice.Text=message;UpdatePreparation();},token);questIndex=null;documentKey="";message=result.Failed==0?"Bibliothèque prête · "+result.Ready+" guides chargés et disponibles hors ligne.":"Préparation incomplète · "+result.Ready+" / "+result.Total+" guides prêts, "+result.Failed+" indisponibles. Réessayez pour compléter les guides manquants.";}finally{preparingLibrary=false;UpdatePreparation();}}
 void PrepareOffline(){if(testing||busy)return;if(store.Value.catalogue.Count==0){catalogueAttempted=false;LoadDefaultLibrary();return;}RunDownload(async token=>{if(cancel!=null)cancel.CancelAfter(TimeSpan.FromMinutes(30));await PrepareAllGuides(token);if(options!=null)BuildOptions(options);});}
 void SetLibraryBusy(){if(libraryBody!=null)libraryBody.IsEnabled=!busy;if(libraryTabs!=null)libraryTabs.IsEnabled=!busy;if(overlayAction!=null)overlayAction.IsEnabled=!busy&&libraryPrimaryEnabled!=null&&libraryPrimaryEnabled();if(cancelLibrary!=null)cancelLibrary.Visibility=busy?Visibility.Visible:Visibility.Collapsed;}
 void LoadDefaultLibrary(){if(testing||catalogueAttempted||busy)return;catalogueAttempted=true;RunDownload(async token=>{if(cancel!=null)cancel.CancelAfter(TimeSpan.FromMinutes(30));if(store.Value.catalogue.Count==0){int loaded=0;try{GuideLibrary.Merge(store,TougliReader.Catalogue(await Download("/api/guide/list",token)));loaded++;}catch(OperationCanceledException){throw;}catch{}try{GuideLibrary.Merge(store,GanymedeReader.Catalogue(await DownloadAddress(GanymedeReader.Site+"/tree?view=list",token)));loaded++;}catch(OperationCanceledException){throw;}catch{}if(loaded==0)throw new IOException("Les catalogues sont indisponibles. La préparation reprendra à la prochaine ouverture.");}await PrepareAllGuides(token);if(options!=null)BuildOptions(options);});}
 async void RunDownload(Func<CancellationToken,Task> operation){if(busy)return;busy=true;cancel=new CancellationTokenSource();cancel.CancelAfter(TimeSpan.FromSeconds(50));SetLibraryBusy();if(libraryNotice!=null)libraryNotice.Text="Chargement en cours…";RefreshView();try{await operation(cancel.Token);}catch(OperationCanceledException){message="Chargement annulé. Progression conservée.";}catch(Exception ex){message="Chargement impossible : "+ex.Message+" Votre dernier guide et votre progression sont conservés.";if(IsLoaded)MessageBox.Show(message,"Tougli");}finally{busy=false;cancel.Dispose();cancel=null;SetLibraryBusy();if(libraryNotice!=null)libraryNotice.Text=message;if(!closing)RefreshView();}}
 internal static Task<string> Download(string endpoint,CancellationToken token){return DownloadAddress(TougliReader.Api+endpoint,token);}
 internal static async Task<string> DownloadAddress(string address,CancellationToken token){var uri=new Uri(address);if(uri.Scheme!="https"||!String.IsNullOrEmpty(uri.UserInfo)||(uri.Host!="api.tougli.barbofus.com"&&uri.Host!="ganymede-app.com"))throw new InvalidDataException("Source de guide non reconnue.");ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;using(var http=new HttpClient(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(45)})using(var response=await http.GetAsync(address,HttpCompletionOption.ResponseHeadersRead,token)){response.EnsureSuccessStatusCode();if(response.Content.Headers.ContentLength>TougliReader.MaxBytes)throw new InvalidDataException("Guide trop volumineux.");using(var input=await response.Content.ReadAsStreamAsync())using(var output=new MemoryStream()){var buffer=new byte[16384];int count;while((count=await input.ReadAsync(buffer,0,buffer.Length,token))>0){if(output.Length+count>TougliReader.MaxBytes)throw new InvalidDataException("Guide trop volumineux.");output.Write(buffer,0,count);}return Encoding.UTF8.GetString(output.ToArray());}}}
 internal Window OptionsPreview(bool guides=false){optionsSection=guides?"guides":"personnage";var window=new Window{Width=960,Height=850,Resources=Resources};BuildOptions(window);return window;}
 internal static void RenderPreview(Window window,string path){var element=(FrameworkElement)window.Content;element.Width=window.Width;element.Height=window.Height;element.Measure(new Size(window.Width,window.Height));element.Arrange(new Rect(0,0,window.Width,window.Height));element.UpdateLayout();var bitmap=new RenderTargetBitmap((int)window.Width,(int)window.Height,96,96,PixelFormats.Pbgra32);bitmap.Render(element);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(path))encoder.Save(file);}
 internal void Render(string path){var element=(FrameworkElement)Content;element.Width=Width;element.Height=Height;element.Measure(new Size(Width,Height));element.Arrange(new Rect(0,0,Width,Height));element.UpdateLayout();var bitmap=new RenderTargetBitmap((int)Width,(int)Height,96,96,PixelFormats.Pbgra32);bitmap.Render(element);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(path))encoder.Save(f);}
